cd /tmp/sv-ca4046fbc8f64f4b83515152353d5246/advanced-multi-complexity && dotnet package list --format json 2>/dev/null | tee /tmp/after-pkg.json | wc -c && cp /tmp/after-pkg.json after-cpm-packages.json && python3 -c "
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            tfm = fw['framework']
            for pkg in fw['topLevelPackages']:
                key = (name, tfm, pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    proj, tfm, pkg = key
    bv = b.get(key, 'N/A')
    av = a.get(key, 'N/A')
    if bv != av:
        changes.append((proj, tfm, pkg, bv, av))
    else:
        unchanged.append((proj, tfm, pkg, bv))

if changes:
    print('=== CHANGES ===')
    for proj, tfm, pkg, bv, av in changes:
        print(f'{proj} ({tfm}): {pkg} {bv} -> {av}')
else:
    print('No version changes detected.')

print(f'\n=== SUMMARY: {len(changes)} changed, {len(unchanged)} unchanged ===')
"

